//! Host-controlled assistant-to-person handoff. This view never contacts a support service.
use crate::primitives::{
    editor::{EditEvent, Editor, InputMode},
    family::{Paint, Slide, Tone, face},
    glyph::{Glyph, icon},
    nav::tr,
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HandoffStage {
    Assistant,
    Transferring,
    Connected,
    Unavailable,
    Resolved,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HandoffAuthor {
    Customer,
    Assistant,
    Agent,
}
#[derive(Clone)]
pub struct HandoffMessage {
    pub id: SharedString,
    pub author: HandoffAuthor,
    pub text: SharedString,
    pub time: SharedString,
    pub after_handoff: bool,
}
impl HandoffMessage {
    pub fn new(
        id: impl Into<SharedString>,
        author: HandoffAuthor,
        text: impl Into<SharedString>,
    ) -> Self {
        Self {
            id: id.into(),
            author,
            text: text.into(),
            time: "".into(),
            after_handoff: false,
        }
    }
    pub fn after_handoff(mut self) -> Self {
        self.after_handoff = true;
        self
    }
    pub fn time(mut self, time: impl Into<SharedString>) -> Self {
        self.time = time.into();
        self
    }
}
#[derive(Clone)]
pub struct HandoffSummary {
    pub issue: SharedString,
    pub fields: Vec<(SharedString, SharedString)>,
}
impl HandoffSummary {
    pub fn new(issue: impl Into<SharedString>) -> Self {
        Self {
            issue: issue.into(),
            fields: Vec::new(),
        }
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AgentHandoffEvent {
    Request { ticket: u64 },
    Cancel { ticket: u64 },
    Send { ticket: u64, text: SharedString },
    CancelSend { ticket: u64 },
}
#[derive(Default)]
struct RequestGate {
    serial: u64,
    active: Option<u64>,
}
impl RequestGate {
    fn begin(&mut self) -> u64 {
        self.serial = self.serial.wrapping_add(1);
        self.active = Some(self.serial);
        self.serial
    }
    fn cancel(&mut self) -> Option<u64> {
        self.active.take()
    }
    fn settle(&mut self, ticket: u64) -> bool {
        if self.active == Some(ticket) {
            self.active = None;
            true
        } else {
            false
        }
    }
}
fn draft_is_unchanged(sent: Option<&str>, current: &str) -> bool {
    sent == Some(current)
}
pub struct AgentHandoff {
    title: SharedString,
    subtitle: SharedString,
    task: SharedString,
    summary: HandoffSummary,
    messages: Vec<HandoffMessage>,
    stage: HandoffStage,
    agent: SharedString,
    estimate: SharedString,
    error: SharedString,
    summary_open: bool,
    summary_motion: Slide,
    summary_height: Rc<Cell<Pixels>>,
    transfer: RequestGate,
    sending: RequestGate,
    sent_text: Option<String>,
    send_error: SharedString,
    composer: Entity<Editor>,
    scroll: ScrollHandle,
    previous_count: usize,
    _subscription: Subscription,
}
impl EventEmitter<AgentHandoffEvent> for AgentHandoff {}
impl AgentHandoff {
    pub fn new(
        title: impl Into<SharedString>,
        task: impl Into<SharedString>,
        summary: HandoffSummary,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        let composer = cx.new(|cx| {
            let mut editor = Editor::new(tr(cx, "Message", "消息"), InputMode::InlineMulti, w, cx);
            editor.set_placeholder(tr(cx, "Write a message…", "输入消息…"));
            editor
        });
        let sub = cx.subscribe_in(&composer, w, |s: &mut Self, _, event: &EditEvent, _, cx| {
            if *event == EditEvent::Submitted {
                s.send(cx);
            }
        });
        Self {
            title: title.into(),
            subtitle: "".into(),
            task: task.into(),
            summary,
            messages: Vec::new(),
            stage: HandoffStage::Assistant,
            agent: "".into(),
            estimate: "".into(),
            error: "".into(),
            summary_open: true,
            summary_motion: Slide::new(1.),
            summary_height: Rc::new(Cell::new(px(80.))),
            transfer: RequestGate::default(),
            sending: RequestGate::default(),
            sent_text: None,
            send_error: "".into(),
            composer,
            scroll: ScrollHandle::new(),
            previous_count: 0,
            _subscription: sub,
        }
    }
    pub fn subtitle(mut self, subtitle: impl Into<SharedString>) -> Self {
        self.subtitle = subtitle.into();
        self
    }
    pub fn estimate(mut self, estimate: impl Into<SharedString>) -> Self {
        self.estimate = estimate.into();
        self
    }
    pub fn set_messages(&mut self, messages: Vec<HandoffMessage>, cx: &mut Context<Self>) {
        self.messages = messages;
        cx.notify();
    }
    /// Append a message once by stable host ID.
    pub fn append_message(&mut self, message: HandoffMessage, cx: &mut Context<Self>) -> bool {
        if self
            .messages
            .iter()
            .any(|existing| existing.id == message.id)
        {
            return false;
        }
        self.messages.push(message);
        cx.notify();
        true
    }
    pub fn set_summary(&mut self, summary: HandoffSummary, cx: &mut Context<Self>) {
        self.summary = summary;
        cx.notify();
    }
    pub fn stage(&self) -> HandoffStage {
        self.stage
    }
    pub fn request_human(&mut self, cx: &mut Context<Self>) {
        if !matches!(
            self.stage,
            HandoffStage::Assistant | HandoffStage::Unavailable
        ) || self.transfer.active.is_some()
        {
            return;
        }
        let ticket = self.transfer.begin();
        self.stage = HandoffStage::Transferring;
        self.error = "".into();
        cx.emit(AgentHandoffEvent::Request { ticket });
        cx.notify();
    }
    pub fn cancel_transfer(&mut self, cx: &mut Context<Self>) {
        if let Some(ticket) = self.transfer.cancel() {
            self.stage = HandoffStage::Assistant;
            cx.emit(AgentHandoffEvent::Cancel { ticket });
            cx.notify();
        }
    }
    /// The host must return the request ticket; late completions after cancellation are ignored.
    pub fn connect(
        &mut self,
        ticket: u64,
        agent: impl Into<SharedString>,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.stage != HandoffStage::Transferring || !self.transfer.settle(ticket) {
            return false;
        }
        self.agent = agent.into();
        self.stage = HandoffStage::Connected;
        cx.notify();
        true
    }
    pub fn fail_transfer(
        &mut self,
        ticket: u64,
        error: impl Into<SharedString>,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.stage != HandoffStage::Transferring || !self.transfer.settle(ticket) {
            return false;
        }
        self.error = error.into();
        self.stage = HandoffStage::Unavailable;
        cx.notify();
        true
    }
    pub fn set_resolved(&mut self, resolved: bool, cx: &mut Context<Self>) {
        if matches!(self.stage, HandoffStage::Connected | HandoffStage::Resolved) {
            self.stage = if resolved {
                HandoffStage::Resolved
            } else {
                HandoffStage::Connected
            };
            cx.notify();
        }
    }
    fn send(&mut self, cx: &mut Context<Self>) {
        if self.stage == HandoffStage::Resolved || self.sending.active.is_some() {
            return;
        }
        let draft = self.composer.read(cx).value().to_owned();
        let text = draft.trim().to_owned();
        if text.is_empty() {
            return;
        }
        let ticket = self.sending.begin();
        self.sent_text = Some(draft);
        self.send_error = "".into();
        cx.emit(AgentHandoffEvent::Send {
            ticket,
            text: text.into(),
        });
        cx.notify();
    }
    fn cancel_send(&mut self, cx: &mut Context<Self>) {
        if let Some(ticket) = self.sending.cancel() {
            self.sent_text = None;
            cx.emit(AgentHandoffEvent::CancelSend { ticket });
            cx.notify();
        }
    }
    /// On success clear only an unchanged draft; failure keeps it available for retry.
    pub fn finish_send(
        &mut self,
        ticket: u64,
        result: Result<(), SharedString>,
        w: &Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if !self.sending.settle(ticket) {
            return false;
        }
        let sent = self.sent_text.take();
        match result {
            Ok(()) => {
                if draft_is_unchanged(sent.as_deref(), self.composer.read(cx).value()) {
                    self.composer.update(cx, |e, cx| e.set_value("", w, cx));
                }
                self.send_error = "".into();
            }
            Err(error) => self.send_error = error,
        }
        cx.notify();
        true
    }
}
fn message_view(
    message: &HandoffMessage,
    agent: &str,
    p: Paint,
    radius: Pixels,
    cx: &App,
) -> impl IntoElement {
    let own = message.author == HandoffAuthor::Customer;
    let name: SharedString = match message.author {
        HandoffAuthor::Customer => tr(cx, "You", "你").into(),
        HandoffAuthor::Assistant => tr(cx, "Assistant", "智能助手").into(),
        HandoffAuthor::Agent => agent.to_owned().into(),
    };
    div()
        .flex()
        .flex_col()
        .when(own, |v| v.items_end())
        .child(
            div()
                .min_h(px(28.))
                .flex()
                .items_center()
                .text_size(px(12.))
                .line_height(px(16.))
                .text_color(p.secondary)
                .child(format!("{} {}", name, message.time)),
        )
        .child(
            div()
                .max_w(px(440.))
                .min_h(px(36.))
                .py(px(8.))
                .px(px(12.))
                .rounded(radius)
                .bg(if own { p.bright } else { p.tray })
                .text_color(if own { p.inverse } else { p.ink })
                .child(message.text.clone()),
        )
}
impl Render for AgentHandoff {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let radius = crate::foundation::surface_radius(cx);
        let progress = self.summary_motion.get(w, cx).clamp(0., 1.);
        if self.messages.len() != self.previous_count {
            if self.scroll.max_offset().y + self.scroll.offset().y < px(24.) {
                self.scroll.scroll_to_bottom();
            }
            self.previous_count = self.messages.len();
        }
        let label = match self.stage {
            HandoffStage::Assistant => tr(cx, "Assistant", "智能助手"),
            HandoffStage::Transferring => tr(cx, "Connecting", "正在转接"),
            HandoffStage::Connected => tr(cx, "Connected", "已接入"),
            HandoffStage::Unavailable => tr(cx, "No one available", "暂时无人接入"),
            HandoffStage::Resolved => tr(cx, "Resolved", "已解决"),
        };
        let mut thread = div()
            .id("handoff-thread")
            .role(Role::Region)
            .aria_label(tr(cx, "Conversation", "会话记录"))
            .tab_index(0)
            .track_scroll(&self.scroll)
            .overflow_y_scroll()
            .flex_1()
            .min_h(px(0.))
            .flex()
            .flex_col()
            .gap(px(12.))
            .pt(px(20.))
            .pr(px(20.))
            .pb(px(20.))
            .pl(px(12.));
        for message in self
            .messages
            .iter()
            .filter(|message| !message.after_handoff)
        {
            thread = thread.child(message_view(message, &self.agent, p, radius, cx));
        }
        if self.stage == HandoffStage::Assistant {
            thread = thread.child(
                face(
                    "handoff-request",
                    tr(cx, "Talk to a person", "联系人工"),
                    36.,
                    8.,
                    Tone::Surface,
                    cx,
                )
                .pl(px(12.))
                .pr(px(14.))
                .gap(px(6.))
                .hover(|s| s.bg(p.tray))
                .child(tr(cx, "Talk to a person", "联系人工"))
                .on_click(cx.listener(|s, _, _, cx| s.request_human(cx))),
            );
        }
        if self.stage != HandoffStage::Assistant {
            let mut card = div()
                .w_full()
                .rounded(radius)
                .border_1()
                .border_color(p.line)
                .bg(p.panel)
                .flex()
                .flex_col()
                .child(
                    div()
                        .min_h(px(62.))
                        .pt(px(12.))
                        .pr(px(12.))
                        .pb(px(12.))
                        .pl(px(16.))
                        .flex()
                        .flex_col()
                        .justify_center()
                        .text_size(px(14.))
                        .line_height(px(20.))
                        .text_color(p.ink)
                        .child(label),
                );
            if self.stage == HandoffStage::Transferring {
                card = card
                    .child(
                        div()
                            .text_size(px(12.))
                            .text_color(p.secondary)
                            .child(self.estimate.clone()),
                    )
                    .child(
                        face(
                            "handoff-cancel",
                            tr(cx, "Cancel transfer", "取消转接"),
                            32.,
                            8.,
                            Tone::Clear,
                            cx,
                        )
                        .px_2()
                        .child(tr(cx, "Cancel", "取消"))
                        .on_click(cx.listener(|s, _, _, cx| s.cancel_transfer(cx))),
                    );
            }
            if self.stage == HandoffStage::Unavailable {
                card = card
                    .child(
                        div()
                            .id("handoff-error")
                            .role(Role::Alert)
                            .text_color(p.danger)
                            .child(self.error.clone()),
                    )
                    .child(
                        face(
                            "handoff-retry",
                            tr(cx, "Try again", "重试"),
                            32.,
                            8.,
                            Tone::Surface,
                            cx,
                        )
                        .px_2()
                        .child(tr(cx, "Try again", "重试"))
                        .on_click(cx.listener(|s, _, _, cx| s.request_human(cx))),
                    );
            }
            if matches!(self.stage, HandoffStage::Connected | HandoffStage::Resolved) {
                card = card.child(
                    div()
                        .text_size(px(12.))
                        .text_color(p.secondary)
                        .child(self.agent.clone()),
                );
            }
            let open = self.summary_open;
            card = card.child(
                face(
                    "handoff-summary-toggle",
                    tr(cx, "Shared summary", "共享摘要"),
                    32.,
                    8.,
                    Tone::Clear,
                    cx,
                )
                .aria_expanded(open)
                .w_full()
                .py(px(8.))
                .pl(px(16.))
                .pr(px(12.))
                .justify_between()
                .text_color(p.secondary)
                .hover(|s| s.bg(p.tray.opacity(0.6)).text_color(p.ink))
                .child(tr(cx, "Shared summary", "共享摘要"))
                .on_click(cx.listener(|s, _, _, cx| {
                    s.summary_open = !s.summary_open;
                    s.summary_motion
                        .duration(f32::from(s.summary_open), 0.24, cx);
                    cx.notify();
                })),
            );
            if progress > 0.001 {
                let height = self.summary_height.clone();
                let mut body = div()
                    .relative()
                    .flex()
                    .flex_col()
                    .gap(px(4.))
                    .pt(px(12.))
                    .px(px(16.))
                    .pb(px(16.))
                    .text_size(px(12.))
                    .line_height(px(16.))
                    .text_color(p.secondary)
                    .child(self.summary.issue.clone());
                for (name, value) in &self.summary.fields {
                    body = body.child(format!("{}: {}", name, value));
                }
                body = body.child(
                    canvas(
                        move |b, w, _| {
                            if (height.get() - b.size.height).abs() > px(0.5) {
                                height.set(b.size.height);
                                w.request_animation_frame();
                            }
                        },
                        |_, _, _, _| (),
                    )
                    .absolute()
                    .inset_0(),
                );
                card = card.child(
                    div()
                        .h(self.summary_height.get() * progress)
                        .overflow_hidden()
                        .child(body),
                );
            }
            thread = thread.child(card);
        }
        for message in self.messages.iter().filter(|message| message.after_handoff) {
            thread = thread.child(message_view(message, &self.agent, p, radius, cx));
        }
        let mut root = div()
            .id("agent-handoff")
            .role(Role::Group)
            .aria_label(self.title.clone())
            .w_full()
            .max_w(px(560.))
            .h(px(600.))
            .rounded(radius)
            .border_1()
            .border_color(p.line)
            .bg(p.panel)
            .text_color(p.ink)
            .flex()
            .flex_col()
            .child(
                div()
                    .min_h(px(64.))
                    .pt(px(12.))
                    .pr(px(12.))
                    .pb(px(12.))
                    .pl(px(20.))
                    .border_b_1()
                    .border_color(p.line)
                    .flex()
                    .items_center()
                    .gap(px(12.))
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .child(
                                div()
                                    .text_size(px(14.))
                                    .line_height(px(20.))
                                    .child(self.title.clone()),
                            )
                            .child(
                                div()
                                    .text_size(px(12.))
                                    .line_height(px(16.))
                                    .text_color(p.secondary)
                                    .child(self.subtitle.clone()),
                            ),
                    )
                    .child(
                        div()
                            .id("handoff-status")
                            .role(Role::Status)
                            .h(px(32.))
                            .flex()
                            .items_center()
                            .px(px(4.))
                            .text_size(px(12.))
                            .line_height(px(16.))
                            .text_color(p.secondary)
                            .child(label),
                    ),
            )
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(p.secondary)
                    .px_3()
                    .child(self.task.clone()),
            )
            .child(thread);
        if self.stage != HandoffStage::Resolved {
            let pending = self.sending.active.is_some();
            let action = if pending {
                tr(cx, "Cancel sending", "取消发送")
            } else if self.send_error.is_empty() {
                tr(cx, "Send", "发送")
            } else {
                tr(cx, "Retry send", "重试发送")
            };
            let bar = div()
                .h(px(42.))
                .pl(px(16.))
                .pr(px(4.))
                .flex()
                .items_center()
                .gap(px(8.))
                .rounded(radius)
                .border_1()
                .border_color(p.line)
                .child(div().flex_1().min_w(px(0.)).child(self.composer.clone()))
                .child(
                    face("handoff-send", action, 32., 8., Tone::Surface, cx)
                        .size(px(32.))
                        .rounded(px(8.))
                        .p_0()
                        .child(icon(Glyph::Send, 16., p.ink))
                        .on_click(cx.listener(move |s, _, _, cx| {
                            if pending {
                                s.cancel_send(cx)
                            } else {
                                s.send(cx)
                            }
                        })),
                );
            let mut footer = div().m(px(12.)).flex().flex_col().gap(px(8.));
            if !self.send_error.is_empty() {
                footer = footer.child(
                    div()
                        .id("handoff-send-error")
                        .role(Role::Alert)
                        .text_size(px(12.))
                        .text_color(p.danger)
                        .child(self.send_error.clone()),
                );
            }
            root = root.child(footer.child(bar));
        }
        root
    }
}
#[cfg(test)]
mod tests {
    use super::{RequestGate, draft_is_unchanged};
    #[test]
    fn cancelled_or_superseded_transfer_cannot_complete() {
        let mut gate = RequestGate::default();
        let first = gate.begin();
        assert_eq!(gate.cancel(), Some(first));
        let second = gate.begin();
        assert!(!gate.settle(first));
        assert!(gate.settle(second));
        assert!(!gate.settle(second));
    }
    #[test]
    fn successful_send_preserves_a_draft_edited_while_waiting() {
        assert!(draft_is_unchanged(Some("hello"), "hello"));
        assert!(!draft_is_unchanged(Some("hello"), "hello there"));
        assert!(!draft_is_unchanged(Some("hello"), " hello"));
        assert!(!draft_is_unchanged(None, "hello"));
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

